"""Pixel Arena tutorial A/B: clean the arena-panel export and test the release rule.

Release rule (telemetry/README.md): ship a variant only if its completion gain is
significant at the 5% level. Export quirks handled here: ETL resends rows (dedupe on
session_id), `variant` may be lowercase or space-padded.
"""
import csv, math, random, statistics, collections, json

SRC = "telemetry/playtest_ab.csv"
OUT = "result.json"
SEED = 7


def load_sessions(path=SRC):
    """session_id-keyed sessions, variant normalised; exact duplicate rows collapsed."""
    sessions, dup_rows, raw_rows, conflicts = {}, 0, 0, 0
    for r in csv.DictReader(open(path, newline="", encoding="utf-8-sig")):
        raw_rows += 1
        sid = r["session_id"].strip()
        rec = {
            "variant": r["variant"].strip().lower(),
            "player": r["player_id"].strip(),
            "done": int(r["completed_tutorial"]),
        }
        if sid in sessions:
            dup_rows += 1
            if sessions[sid] != rec:
                conflicts += 1
                print(f"WARN session {sid} resent with conflicting fields: {sessions[sid]} vs {rec}")
            continue
        sessions[sid] = rec
    return sessions, dup_rows, raw_rows, conflicts


def two_proportion_test(ka, na, kb, nb):
    pooled = (ka + kb) / (na + nb)
    z = (kb / nb - ka / na) / math.sqrt(pooled * (1 - pooled) * (1 / na + 1 / nb))
    return z, math.erfc(abs(z) / math.sqrt(2))


def fisher_exact(ka, na, kb, nb):
    """Two-sided Fisher exact by direct hypergeometric summation."""
    k_total, n_total = ka + kb, na + nb
    pmf = lambda x: math.comb(na, x) * math.comb(nb, k_total - x) / math.comb(n_total, k_total)
    p_obs = pmf(ka)
    return sum(pmf(x) for x in range(max(0, k_total - nb), min(na, k_total) + 1) if pmf(x) <= p_obs * (1 + 1e-9))


def wilson(k, n, z=1.96):
    p, d = k / n, 1 + z * z / n
    c, h = (p + z * z / (2 * n)) / d, z * math.sqrt(p * (1 - p) / n + z * z / (4 * n * n)) / d
    return round(c - h, 4), round(c + h, 4)


def player_bootstrap(sessions, draws=20000, seed=SEED):
    """Resample PLAYERS, not sessions: 366/763 players appear in both arms, so sessions
    are clustered and the naive interval is optimistic."""
    by_player = collections.defaultdict(list)
    for s in sessions.values():
        by_player[s["player"]].append(s)
    players = list(by_player)
    rng = random.Random(seed)
    diffs = []
    for _ in range(draws):
        sample = [by_player[rng.choice(players)] for _ in players]
        a = [s for g in sample for s in g if s["variant"] == "a"]
        b = [s for g in sample for s in g if s["variant"] == "b"]
        diffs.append(sum(s["done"] for s in b) / len(b) - sum(s["done"] for s in a) / len(a))
    diffs.sort()
    p_two = 2 * min(sum(1 for x in diffs if x <= 0), sum(1 for x in diffs if x >= 0)) / len(diffs)
    return round(diffs[int(0.025 * len(diffs))], 4), round(diffs[int(0.975 * len(diffs))], 4), round(min(p_two, 1.0), 4)


def within_player_test(sessions):
    """Paired check on players who saw both arms: removes any player-composition confound."""
    by_player = collections.defaultdict(list)
    for s in sessions.values():
        by_player[s["player"]].append(s)
    diffs = []
    for group in by_player.values():
        a = [s["done"] for s in group if s["variant"] == "a"]
        b = [s["done"] for s in group if s["variant"] == "b"]
        if a and b:
            diffs.append(sum(b) / len(b) - sum(a) / len(a))
    m = statistics.mean(diffs)
    se = statistics.stdev(diffs) / math.sqrt(len(diffs))
    t = m / se
    return len(diffs), round(m, 4), round(t, 3), round(math.erfc(abs(t) / math.sqrt(2)), 5)


def _groups_by_player(sessions):
    by_player = collections.defaultdict(list)
    for s in sessions.values():
        by_player[s["player"]].append(s)
    return by_player


